import{_ as s,C as l,o as e,c,a2 as t,b as o,w as r,a as d,E as h,a3 as p}from"./chunks/framework.CWWEQfK7.js";const _=JSON.parse('{"title":"耳鼠 Ershu","description":"把多个私有代码仓库整理成团队和 AI 都能查询的内部 Wiki，并保留回到源码核对的依据。","frontmatter":{"page_id":"home","layout":"home","title":"耳鼠 Ershu","description":"把多个私有代码仓库整理成团队和 AI 都能查询的内部 Wiki，并保留回到源码核对的依据。","hero":{"name":"耳鼠 Ershu","text":"把多个代码仓库，变成团队和 AI 都能查的内部 Wiki","tagline":"Ershu 从当前源码整理项目文档、代码索引、接口关系和跨仓库依赖。开发者在网页里阅读和搜索，AI 编程工具通过 MCP 查询同一份项目上下文。","image":{"src":"/favicon.ico","alt":"耳鼠 Ershu 标志"},"actions":[{"theme":"brand","text":"在一台机器上跑起来","link":"/guide/quick-start"},{"theme":"alt","text":"看它解决哪些问题","link":"/overview/use-cases"}]},"features":[{"title":"从当前代码生成 Wiki","details":"按项目和仓库整理模块、流程与接口，引用可以继续回到对应源码核对。"},{"title":"跨仓库理解一个产品","details":"把前端、后端、微服务和共享库放进同一个项目，不再靠人手拼接上下文。"},{"title":"给 AI 一份稳定的项目记忆","details":"通过只读 MCP 按需查询文档、目录、代码索引、关系和接口约定，不必每次从零扫描。"},{"title":"部署在自己的环境里","details":"项目权限、仓库凭据、模型通道和存储由团队管理，适合私有代码场景。"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1786627803000}'),m={name:"index.md"};function n(E,a,A,u,B,b){const i=l("Mermaid");return e(),c("div",null,[a[1]||(a[1]=t('<h2 id="vibe-coding-变快了-理解项目并没有" tabindex="-1">Vibe coding 变快了，理解项目并没有 <a class="header-anchor" href="#vibe-coding-变快了-理解项目并没有" aria-label="Permalink to &quot;Vibe coding 变快了，理解项目并没有&quot;">​</a></h2><p>AI 很会补全眼前的一段代码，却未必知道这个页面依赖哪个服务、一次改动会穿过哪些仓库、旧文档还能不能信。项目越大，这些问题越容易把生成代码的速度抵消掉。</p><div class="home-card-grid home-card-grid--four"><article class="home-card home-card--compact"><p class="home-card-label">上下文反复重建</p><h3>每个任务都从“先读懂项目”开始</h3><p>开发者和 AI 一遍遍搜索入口、配置和调用关系，同样的理解成本被重复支付。</p></article><article class="home-card home-card--compact"><p class="home-card-label">跨仓库容易漏改</p><h3>打开了一个仓库，却在改整个产品</h3><p>前端、接口、消息和数据结构分别维护，只看当前目录很难发现真正的影响范围。</p></article><article class="home-card home-card--compact"><p class="home-card-label">文档跟不上代码</p><h3>Wiki 有答案，但没人敢确定它还对不对</h3><p>说明与提交脱节后，团队只能回头问维护者，AI 也可能把旧结论当成当前事实。</p></article><article class="home-card home-card--compact"><p class="home-card-label">知识集中在少数人</p><h3>维护者成了项目的人肉搜索框</h3><p>新人、测试、产品和支持团队都在重复询问同一批边界、流程和历史原因。</p></article></div><aside class="home-statement"><p class="home-statement-label">Ershu 做的事</p><p class="home-statement-title">把分散在仓库和维护者脑中的项目知识，整理成能搜索、能追溯、能持续更新的共同上下文。</p><p>它不会替团队决定代码该怎么改。它先把项目结构、文档、关系和来源准备好，让人和 AI 少猜一点，也更容易检查自己的结论。</p></aside><h2 id="这份-wiki-不只给开发者看" tabindex="-1">这份 Wiki 不只给开发者看 <a class="header-anchor" href="#这份-wiki-不只给开发者看" aria-label="Permalink to &quot;这份 Wiki 不只给开发者看&quot;">​</a></h2><p>同一份项目知识可以服务不同角色。每个人看到的入口不同，但不必再各自维护一套互相矛盾的说明。</p><table tabindex="0"><thead><tr><th>谁会用</th><th>能直接解决的问题</th></tr></thead><tbody><tr><td>新加入的开发者</td><td>先看项目全貌、仓库边界、关键入口和主要流程，再决定从哪里读源码</td></tr><tr><td>日常维护者</td><td>用关键词或含义搜索跨仓库定位实现，并从文档引用回到具体文件和行号</td></tr><tr><td>技术负责人和架构师</td><td>查看依赖关系、接口约定、改动影响面和静态运行路径，缩小评审范围</td></tr><tr><td>测试人员</td><td>从接口、消息、数据结构和业务流程理解应该覆盖哪些输入、输出与异常路径</td></tr><tr><td>产品、支持和交付团队</td><td>不必先学会浏览每个仓库，也能查清一个功能由哪些模块共同完成</td></tr><tr><td>AI 编程工具</td><td>通过项目范围的只读 MCP 取得结构化上下文，并看到版本、新鲜度和截断提示</td></tr></tbody></table><h2 id="wiki-之外-还有搜索、关系、契约和更新" tabindex="-1">Wiki 之外，还有搜索、关系、契约和更新 <a class="header-anchor" href="#wiki-之外-还有搜索、关系、契约和更新" aria-label="Permalink to &quot;Wiki 之外，还有搜索、关系、契约和更新&quot;">​</a></h2><div class="home-card-grid home-card-grid--four"><article class="home-card home-card--compact"><p class="home-card-label">搜索</p><h3>知道名字就搜名字，不知道名字就搜含义</h3><p>关键词、语义和混合搜索覆盖代码与文档，并明确告诉你语义能力是否发生降级。</p></article><article class="home-card home-card--compact"><p class="home-card-label">关系</p><h3>从一个入口追到跨仓库影响范围</h3><p>知识图谱、变更面和静态运行路径帮助团队找到候选依赖，再回到源码确认。</p></article><article class="home-card home-card--compact"><p class="home-card-label">契约</p><h3>把服务之间说好的事情单独整理出来</h3><p>从 OpenAPI、GraphQL、Protobuf、消息通道和数据结构等来源提取接口事实，方便调用方核对。</p></article><article class="home-card home-card--compact"><p class="home-card-label">更新</p><h3>代码变了，项目事实可以跟着刷新</h3><p>完整分析建立基线后，可以通过手动任务、计划轮询或签名 Webhook 更新目录、索引和关系。</p></article></div><h2 id="一次分析-给人和-ai-两个入口" tabindex="-1">一次分析，给人和 AI 两个入口 <a class="header-anchor" href="#一次分析-给人和-ai-两个入口" aria-label="Permalink to &quot;一次分析，给人和 AI 两个入口&quot;">​</a></h2>',10)),(e(),o(p,null,{default:r(()=>[h(i,{id:"mermaid-83",class:"ershu-mermaid",graph:"flowchart%20LR%0A%20%20Repos%5B%22%E5%89%8D%E7%AB%AF%E3%80%81%E5%90%8E%E7%AB%AF%E3%80%81%E5%BE%AE%E6%9C%8D%E5%8A%A1%E5%92%8C%E5%85%B1%E4%BA%AB%E5%BA%93%22%5D%20--%3E%20Worker%5B%22Ershu%20%E5%8F%AA%E8%AF%BB%E5%88%86%E6%9E%90%22%5D%0A%20%20Worker%20--%3E%20Knowledge%5B%22%E6%96%87%E6%A1%A3%E3%80%81%E6%90%9C%E7%B4%A2%E7%B4%A2%E5%BC%95%E3%80%81%E4%BB%A3%E7%A0%81%E5%85%B3%E7%B3%BB%E5%92%8C%E6%8E%A5%E5%8F%A3%E7%BA%A6%E5%AE%9A%22%5D%0A%20%20Knowledge%20--%3E%20Web%5B%22%E5%9B%A2%E9%98%9F%E9%80%9A%E8%BF%87%E7%BD%91%E9%A1%B5%E9%98%85%E8%AF%BB%E3%80%81%E6%90%9C%E7%B4%A2%E5%92%8C%E8%BF%BD%E6%BA%AF%22%5D%0A%20%20Knowledge%20--%3E%20MCP%5B%22AI%20%E7%BC%96%E7%A8%8B%E5%B7%A5%E5%85%B7%E9%80%9A%E8%BF%87%20MCP%20%E6%8C%89%E9%9C%80%E6%9F%A5%E8%AF%A2%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>网页适合浏览项目、阅读 Wiki、搜索、查看图谱和跟踪分析任务。MCP 适合让开发智能体先发现项目，再逐步读取文档、目录、符号、关系和有限范围的源码。两边使用相同的项目权限和已保存结果。</p><h2 id="适合与不适合" tabindex="-1">适合与不适合 <a class="header-anchor" href="#适合与不适合" aria-label="Permalink to &quot;适合与不适合&quot;">​</a></h2><p>Ershu 更适合由多个仓库共同交付、需要自行管理代码和模型访问、并且已经把 AI 编程带入日常开发的团队。它也适合接手遗留系统，或重新整理长期缺少可靠文档的项目。</p><p>下面这些边界需要提前知道：</p><ul><li>Ershu 是自行部署的软件，不是托管式代码扫描服务。</li><li>第一次分析必须覆盖项目中的全部活动仓库，后续才能做局部或增量更新。</li><li>生成文档用于理解和导航。与当前源码冲突时，以源码和测试为准。</li><li>自行部署不等于代码一定不会离开内网。模型请求会发往你配置的模型服务，数据边界取决于实际网络和模型通道。</li><li>Worker 不执行被分析仓库的通用脚本。可选 LSP 也默认关闭，需要单独评估 Docker 权限和依赖来源。</li></ul><h2 id="从这里开始" tabindex="-1">从这里开始 <a class="header-anchor" href="#从这里开始" aria-label="Permalink to &quot;从这里开始&quot;">​</a></h2><div class="home-path-grid"><a class="home-path-card" href="/overview/use-cases"><span>先判断价值</span><strong>看看 Ershu 对你的团队是否有用</strong><small>从 AI 编程、内部 Wiki、跨仓库改动和团队协作四类问题开始。</small></a><a class="home-path-card" href="/guide/quick-start"><span>先跑起来</span><strong>在一台机器上完成首次部署</strong><small>从安装依赖、启动服务一直走到登录页，每一步都有成功判据。</small></a><a class="home-path-card" href="/guide/create-first-project"><span>开始使用</span><strong>创建项目并生成第一份 Wiki</strong><small>配置模型、添加仓库、建立全项目基线，再检查文档和搜索结果。</small></a><a class="home-path-card" href="/guide/connect-mcp"><span>接入 AI</span><strong>让开发智能体读取 Ershu</strong><small>创建项目范围密钥，并用第一条真实工具调用确认权限和版本。</small></a></div><section class="home-final-cta"><p class="home-card-label">先用一个真实问题验证</p><h2>挑一个团队经常问、又需要翻多个仓库才能回答的问题。</h2><p>完成第一次分析后，用 Wiki、搜索和 MCP 分别找一次答案。能否快速回到正确源码，比首页上的任何口号都更有说服力。</p><div class="home-final-actions"><a class="VPButton medium brand" href="/guide/quick-start">开始部署</a><a class="VPButton medium alt" href="/overview/what-is-ershu">了解工作方式</a></div></section>',8))])}const f=s(m,[["render",n]]);export{_ as __pageData,f as default};
